&lt;/div&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Demi-orque.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
